<?php get_header(); the_post();
$id=get_the_ID(); $model=get_post_meta($id,'_smtp_model',true); $type=get_post_meta($id,'_smtp_product_type',true) ?: 'hardware'; $availability=get_post_meta($id,'_smtp_availability',true) ?: 'available'; $mode=get_post_meta($id,'_smtp_price_mode',true) ?: 'quote'; $price=(float)get_post_meta($id,'_smtp_price',true); $brochure=get_post_meta($id,'_smtp_brochure_url',true); $specs=array_filter(array_map('trim',preg_split('/\r\n|\r|\n/',(string)get_post_meta($id,'_smtp_key_specs',true)))); $brands=get_the_terms($id,'smt_product_brand'); ?>
<main class="single-product-page"><section class="section product-detail-hero"><div class="container product-detail-grid"><div class="product-gallery"><?php if(has_post_thumbnail()) the_post_thumbnail('large'); else echo '<div class="product-placeholder product-placeholder-large"><i class="fa-solid fa-box-open"></i></div>'; ?></div><div class="product-summary"><div class="product-card-meta"><span><?php echo esc_html(ucfirst($type)); ?></span><span class="availability availability-<?php echo esc_attr($availability); ?>"><?php echo esc_html(ucwords(str_replace('-',' ',$availability))); ?></span></div><h1><?php the_title(); ?></h1><?php if($model): ?><p class="product-model">Model: <?php echo esc_html($model); ?></p><?php endif; ?><?php if($brands && !is_wp_error($brands)): ?><p class="product-brand">Brand: <?php echo esc_html(implode(', ',wp_list_pluck($brands,'name'))); ?></p><?php endif; ?><div class="product-excerpt"><?php the_excerpt(); ?></div><?php if($mode==='direct' && $price>0): ?><div class="product-price">EGP <?php echo esc_html(number_format($price,2)); ?><small>Indicative price, excluding applicable taxes and delivery</small></div><?php else: ?><div class="product-price product-price-quote">Commercial pricing available on request</div><?php endif; ?><div class="product-actions"><a class="btn btn-gold" href="#request-quote">Request a Quote</a><?php if($brochure): ?><a class="btn btn-outline" target="_blank" rel="noopener" href="<?php echo esc_url($brochure); ?>">Download Datasheet</a><?php endif; ?></div></div></div></section>
<section class="section ui-surface-section"><div class="container product-content-grid"><article class="product-description"><h2>Product Overview</h2><?php the_content(); ?></article><?php if($specs): ?><aside class="product-specifications"><h2>Key Specifications</h2><ul><?php foreach($specs as $spec): ?><li><i class="fa-solid fa-check"></i><?php echo esc_html($spec); ?></li><?php endforeach; ?></ul></aside><?php endif; ?></div></section>
<section class="section" id="request-quote"><div class="container quote-section-grid"><div><span class="section-kicker">Commercial enquiry</span><h2>Request pricing and availability</h2><p>Tell us your quantity and requirements. Our team will confirm availability, configuration, delivery, support options, and the final commercial offer.</p></div><div class="quote-form-card"><?php echo do_shortcode('[source_more_quote_form product_id="'.$id.'"]'); ?></div></div></section></main><?php get_footer(); ?>
